#include <iostream>
#include <algorithm>
int main() {
    double setpoint = 100.0, measurement = 85.0, kp = 2.5;
    double error = setpoint - measurement;
    double out = std::clamp(kp * error, -20.0, 20.0);
    std::cout << error << " " << out << "\n";
    return 0;
}

#include <iostream>
int main() {
    double alpha = 0.5;
    double y = 10.0;
    double x = 30.0;
    y = alpha * x + (1.0 - alpha) * y;
    std::cout << y << "\n";
    return 0;
}
